def compute(vars):
    total_staff = vars["v1"]
    operations_staff = vars["v2"]

    if total_staff == 0:
        return None

    portion = operations_staff / total_staff

    return {
        "value": portion,
        "trace": {
            "total_staff": total_staff,
            "operations_staff": operations_staff,
            "portion": portion,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
